package com.prism.musepair;
import java.io.*;import java.nio.file.*;import java.nio.file.attribute.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import org.json.*;import okhttp3.*;
// Development-only live verification. Never compiled into the APK.
public class CloudCheck {
 static byte[] read(InputStream in)throws IOException{try(InputStream i=in){ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[1024];int n;while((n=i.read(b))!=-1)o.write(b,0,n);return o.toByteArray();}}
 public static void main(String[] args)throws Exception{
  Path record=Paths.get(args[0]);MuseCloud.Store store=new MuseCloud.Store(){public JSONObject load()throws Exception{return new JSONObject(new String(Files.readAllBytes(record),"UTF-8"));}public void save(JSONObject obj)throws Exception{Path tmp=Files.createTempFile(record.getParent(),"rotation-",".tmp");Files.setPosixFilePermissions(tmp,PosixFilePermissions.fromString("rw-------"));Files.write(tmp,obj.toString().getBytes("UTF-8"));Files.move(tmp,record,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}};
  OkHttpClient.Builder b=new OkHttpClient.Builder().connectTimeout(15,TimeUnit.SECONDS).readTimeout(20,TimeUnit.SECONDS).writeTimeout(20,TimeUnit.SECONDS).pingInterval(20,TimeUnit.SECONDS);
  if(args.length>1)b.proxy(new Proxy(Proxy.Type.HTTP,new InetSocketAddress("127.0.0.1",Integer.parseInt(args[1]))));
  MuseCloud cloud=new MuseCloud(store,b.build());LocalApi local=new LocalApi(cloud);local.start();
  try{java.net.HttpURLConnection check=(java.net.HttpURLConnection)new URL("http://127.0.0.1:18787/transport-check").openConnection();check.setRequestMethod("POST");check.setDoOutput(true);check.getOutputStream().write("{\"text\":\"本机传输\"}".getBytes("UTF-8"));JSONObject receipt=new JSONObject(new String(read(check.getInputStream()),"UTF-8"));if(receipt.optBoolean("muse_sent")||!receipt.optBoolean("received"))throw new AssertionError("local receipt claimed delivery");check.disconnect();System.out.println("PASS Native localhost receipt is not Muse delivery");}catch(Exception e){local.close();cloud.close();throw e;}
  cloud.start();long deadline=System.nanoTime()+90000000000L;String last="";try{
   while(cloud.current==null||!cloud.current.ready){if(System.nanoTime()>deadline)throw new IOException("cloud check timeout: "+cloud.state+" "+cloud.error);String state=cloud.state+" "+cloud.error;if(!last.equals(state)){System.out.println(state);last=state;}Thread.sleep(500);}
   System.out.println("PASS Native Java cloud register + side-chat subscription");
   if(args.length>2&&args[2].equals("send")){java.net.HttpURLConnection request=(java.net.HttpURLConnection)new URL("http://127.0.0.1:18787/messages").openConnection();request.setRequestMethod("POST");request.setDoOutput(true);request.setReadTimeout(70000);request.getOutputStream().write("{\"text\":\"请只回复：眼镜独立链路验证成功。\"}".getBytes("UTF-8"));JSONObject result=new JSONObject(new String(read(request.getInputStream()),"UTF-8"));request.disconnect();if(!result.optBoolean("muse_sent"))throw new AssertionError("send failed");System.out.println("PASS Muse accepted Java client message");deadline=System.nanoTime()+90000000000L;while(System.nanoTime()<deadline){JSONArray replies=cloud.replies.snapshot();for(int i=0;i<replies.length();i++)if(replies.getJSONObject(i).optBoolean("done")){System.out.println("PASS real Muse reply chars="+replies.getJSONObject(i).optString("text").length());return;}Thread.sleep(500);}throw new IOException("reply timeout");}
  }finally{local.close();cloud.close();cloud.client.dispatcher().executorService().shutdown();cloud.client.connectionPool().evictAll();}
 }
}
